from taf.internal.aliasing import aliasing_scope
from taf.ul.mobile.ui.android.mobile import Mobile
from taf.ul.mobile.ui.android.factory import MobileFactory


class android(object):
    """Android mobile UI operation library.

    Mobiles that are currently supported:
        - Huawei Honor (brand: 'HONOR', model:'CDY-AN90', android_version: '10', UI version: 'Magic UI 3.1.1')
        - MediaTek Petrus
        - Qualcomm brand: qti model: lahaina for arm64 android_version: '11'
.. code-block:: Robot

    Example of Test cases:
    *********************

    *** Settings ***
    Library     taf.ul.mobile.ui.android     WITH NAME   android_mobile

    *** Variables ***

    *** Test Cases ***
    Android Mobile UI Test Demo
        android_mobile.setup
        ...   ui_version=Magic UI 3.1.1
        ...   host=10.57.130.x
        ...   username=nokia5G
        ...   password=noki@123
        ...   port=22
        ...   serial_number=0123456789ABCDEF
        ...   alias=test

        android_mobile.Disable Sim Card by Slot Index    slot_index=${0}   mobile=test

        android_mobile.Enable Sim Card by Slot Index    slot_index=${1}   mobile=test

        ${default slot index} =    android_mobile.Get Default Mobile Data Slot Index    mobile=test
        Log    ${default slot index}

        android_mobile.teardown    mobile=test


    *** Keywords ***

    """
    ROBOT_LIBRARY_SCOPE = 'TEST SUITE'

    lookup_handler, configured_mobiles = aliasing_scope(name=__name__, lookup_arg='mobile', lookup_type=Mobile)

    def __init__(self):
        self._mobile_factory = MobileFactory()

    def setup(self, ui_version, host, username, password, port=22, serial_number="", alias=None):
        """
        setup a mobile.
        :param str ui_version: mobile ui version.
            e.g Magic UI 3.1.1, have tested on honor CDY-AN90 1080x2400,
                EMUI 10.1.0, have tested on huawei mate30 LIO-AN00 1176x2400.
                Qualcomm qti lahaina for arm64 ue do not have UI, so this field equal to '' or ${None}
                if mobile is mtk peturs, pass 'petrus' as ui_version.
        :param str host: ue pc ip address.
        :param str username: ue pc username.
        :param str password: ue pc password.
        :param int port: ssh port, default is 22.
        :param str serial_number: .mobile serial number, e.g 0123456789ABCDEF, it can be queried with adb devices command.
        :param str alias: alias to be used in keywords.
        :return Mobile: configured Mobile object.
        """
        configured_mobile = self._mobile_factory.create(
            ui_version=ui_version, host=host, username=username, password=password, port=int(port), serial_number=serial_number)
        configured_mobile.setup()
        self.configured_mobiles.add(configured_mobile, alias)
        return configured_mobile

    @lookup_handler.implicit_lookup
    def disable_sim_card_by_slot_index(self, slot_index, timeout=10, mobile=None):
        """
        Disable SIM card by specified slot index.
        :param int slot_index: sim card slot index, begin with 0.
        :param float timeout: waiting time for sim card switching active, default value is 10s.
        :param str mobile: mobile alias name.
        """
        mobile.disable_sim_card_by_slot_index(int(slot_index), float(timeout))

    @lookup_handler.implicit_lookup
    def enable_sim_card_by_slot_index(self, slot_index, timeout=10, mobile=None):
        """
        Enable SIM card by specified slot index.
        :param int slot_index: sim card slot index, begin with 0.
        :param float timeout: waiting time for sim card switching active, default value is 10s.
        :param str mobile: mobile alias name.
        """
        mobile.enable_sim_card_by_slot_index(int(slot_index), float(timeout))

    @lookup_handler.implicit_lookup
    def get_default_mobile_data_slot_index(self, mobile=None):
        """
        Get default mobile data sim card slot index.
        :param str mobile: mobile alias name.
        :return slot_index: default sim card slot index.
        """
        return mobile.get_default_mobile_data_slot_index()

    @lookup_handler.implicit_lookup
    def wait_until_message_box(self, message_content, timeout, mobile=None):
        """
        Wait until specified message box occur.
        :param str message_content: specified message content in message box.
        :param int timeout: waiting time for message box occuring.
        :param str mobile: mobile alias name.
        :raises MessageNotOccur: if waitting timeout, will raise MessageNotOccur Exception.
        """
        mobile.wait_until_message_box(message_content, float(timeout))

    @lookup_handler.implicit_lookup
    def switch_network_mode(self, mode_name, restart_time=30, mobile=None):
        """
        Switch mobile network mode, verified on Huawei Honor magic_ui_3_1_1.
        :param str mode name: specified the mode name e.g 'NSA mode', 'Auto (default)', 'SA+NSA mode'.
        :param int restart_time: the time (seconds) of UE restart.
        :param str mobile: mobile alias name.
        """
        mobile.switch_network_mode(mode_name, restart_time)

    @lookup_handler.implicit_lookup
    def switch_apn(self, apn_name, mobile=None):
        """
        Switch mobile apn, verified on Huawei Honor magic_ui_3_1_1.
        :param str apn name: specified the mode name e.g 'dxdata2', 'SANSA'.
        :param str mobile: mobile alias name.
        """
        mobile.switch_apn(apn_name)

    @lookup_handler.implicit_lookup
    def set_sim_power_off(self, sim_card_name, mobile=None):
        """
        Only used for setting sim power off with at command in MTK mobile.
        :param str sim_card_name: sim card name showed in engineer mode window, e.g 'SIM 1 - MAIN'.
        :param str mobile: mobile alias name.
        """
        mobile.set_sim_power_off(sim_card_name)

    @lookup_handler.implicit_lookup
    def set_sim_power_on(self, sim_card_name, mobile=None):
        """
        Only used for setting sim power on with at command in MTK mobile.
        :param str sim_card_name: sim card name showed in engineer mode window, e.g 'SIM 1 - MAIN'.
        :param str mobile: mobile alias name.
        """
        mobile.set_sim_power_on(sim_card_name)

    @lookup_handler.implicit_lookup
    def start_emergency_call(self, number, mobile=None):
        """
        Start emergency call with dial.
        Supported MTK Petrus mobile.
        :param int number: emergency call number, e.g 911.
        :param str mobile: mobile alias name.
        """
        mobile.start_emergency_call(number)

    @lookup_handler.implicit_lookup
    def stop_emergency_call(self, mobile=None):
        """
        Stop emergency call in dial.
        Supported MTK Petrus mobile.
        :param str mobile: mobile alias name.
        """
        mobile.stop_emergency_call()

    @lookup_handler.implicit_lookup
    def get_network_mode(self, mobile=None):
        """
        get selected network mode name.
        supported Huawei EMUI 1.10.0 LioAn00, EMUI 10.1.0 EvrAn900 mobile.
        :param str mobile: mobile alias name.
        :return str: network mode name.
        """
        return mobile.get_network_mode()

    @lookup_handler.implicit_lookup
    def get_access_point_name(self, mobile=None):
        """
        get selected access point name.
        supported Huawei EMUI 1.10.0 LioAn00, EMUI 10.1.0 EvrAn900 mobile.
        :param str mobile: mobile alias name.
        :return str: access point name.
        """
        return mobile.get_access_point_name()

    @lookup_handler.implicit_lookup
    def start_debuglogger(self, waiting_time=5, mobile=None):
        """
        start debug logger for petrus.
        :param int waiting_time: wait seconds for operating completely, default 5 seconds.
        :param str mobile: mobile alias name.
        :raises DebugLoggerOperatingFailed: if operate debuglogger failed .
        """
        mobile.start_debuglogger(waiting_time)

    @lookup_handler.implicit_lookup
    def stop_debuglogger(self, waiting_time=5, mobile=None):
        """
        stop debug logger for petrus.
        :param int waiting_time: wait seconds for operating completely, default 5 seconds.
        :param str mobile: mobile alias name.
        :raises DebugLoggerOperatingFailed: if operate debuglogger failed .
        """
        mobile.stop_debuglogger(waiting_time)

    @lookup_handler.implicit_lookup
    def restart_debuglogger(self, waiting_time=5, mobile=None):
        """
        restart debug logger for petrus.
        :param int waiting_time: wait seconds for operating completely, default 5 seconds.
        :param str mobile: mobile alias name.
        :raises DebugLoggerOperatingFailed: if operate debuglogger failed .
        """
        mobile.stop_debuglogger(waiting_time)
        mobile.start_debuglogger(waiting_time)

    @lookup_handler.implicit_lookup
    def start_modemlog(self, waiting_time=5, mobile=None):
        """
        start modemlog in debug logger for petrus.
        :param int waiting_time: wait seconds for operating completely, default 5 seconds.
        :param str mobile: mobile alias name.
        :raises DebugLoggerOperatingFailed: if operate debuglogger failed .
        """
        mobile.start_modemlog(waiting_time)

    @lookup_handler.implicit_lookup
    def stop_modemlog(self, waiting_time=5, mobile=None):
        """
        stop modemlog in debug logger for petrus.
        :param int waiting_time: wait seconds for operating completely, default 5 seconds.
        :param str mobile: mobile alias name.
        :raises DebugLoggerOperatingFailed: if operate debuglogger failed .
        """
        mobile.stop_modemlog(waiting_time)

    @lookup_handler.implicit_lookup
    def restart_modemlog(self, waiting_time=5, mobile=None):
        """
        restart modemlog in debug logger for petrus.
        :param int waiting_time: wait seconds for operating completely, default 5 seconds.
        :param str mobile: mobile alias name.
        :raises DebugLoggerOperatingFailed: if operate debuglogger failed .
        """
        mobile.stop_modemlog(waiting_time)
        mobile.start_modemlog(waiting_time)

    @lookup_handler.implicit_lookup
    def enable_volte_calls(self, mobile=None):
        """
        Enable volte calls for Samsung mobile.
        :param str mobile: mobile alias name.
        :raises SelectFailure: if enable volte calls failed.
        """
        mobile.enable_volte_calls()

    @lookup_handler.implicit_lookup
    def disable_volte_calls(self, mobile=None):
        """
        Disable volte calls for Samsung mobile.
        :param str mobile: mobile alias name.
        :raises SelectFailure: if disable volte calls failed .
        """
        mobile.disable_volte_calls()

    @lookup_handler.implicit_lookup
    def unlock_screen(self, mobile=None):
        """
        Unlock mobile screen when the mobile is sleeping.
        :param str mobile: mobile alias name.
        """
        mobile.unlock_screen()

    @lookup_handler.implicit_lookup
    def get_ue_ip(self, mobile=None):
        """
        Get ue ip.
        :param str mobile: mobile alias name.
        :return str: ue ip or empty str if no UE ip detected.
        """
        return mobile.get_ue_ip()

    @lookup_handler.implicit_lookup
    def enable_airplane(self, mobile=None):
        """
        Enable UE airplane.
        :param str mobile: mobile alias name.
        """
        mobile.enable_airplane()

    @lookup_handler.implicit_lookup
    def disable_airplane(self, mobile=None):
        """
        Disable UE airplane.
        :param str mobile: mobile alias name.
        """
        mobile.disable_airplane()

    @lookup_handler.implicit_lookup
    def enable_mobile_data(self, mobile=None):
        """
        Enable UE mobile data service.
        :param str mobile: mobile alias name.
        """
        return mobile.enable_mobile_data()

    @lookup_handler.implicit_lookup
    def disable_mobile_data(self, mobile=None):
        """
        Disable UE mobile data service.
        :param str mobile: mobile alias name.
        """
        return mobile.disable_mobile_data()

    @lookup_handler.implicit_lookup
    def teardown(self, mobile=None):
        """
        tearwodn the mobile, disconnect the ue pc.
        :param str mobile: mobile alias name.
        """
        mobile.teardown()
